def text_or_none(value, required: bool) -> bool:
    """A required evidence text is a non-empty string; an optional one is a string or null."""
    return isinstance(value, str) and bool(value.strip()) if required else value is None or isinstance(value, str)


def read_signal(runtime, node: str) -> dict:
    """The worker's completion file, validated against the version the run pinned: 1.0.0 before slice 2, 1.1.0 for 2.2.0 features."""
    from .guardrails import COMPLETION_VERSION, completion_version
    path = runtime.directory / f"{node}.completion.json"
    if path.is_symlink() or not path.is_file() or path.stat().st_size > 65536:
        raise ValueError(f"Invalid completion file for {node}")
    item = read_json(path)
    version = completion_version(runtime.plan)
    evidence = version == COMPLETION_VERSION
    expected = COMPLETION_KEYS | EVIDENCE_KEYS if evidence else COMPLETION_KEYS
    if isinstance(item, dict) and item.get("version") in {"1.0.0", COMPLETION_VERSION} and item["version"] != version:
        raise ValueError(f"Completion version {item['version']} refused: this run is pinned at completion {version}")
    if not isinstance(item, dict) or set(item) != expected:
        raise ValueError("Malformed completion signal" + (": version 1.1.0 needs untested, falsifying_check, verify_yourself and question" if evidence else ""))
    if (item["version"] != version or item["run_id"] != runtime.plan["run_id"] or item["node_id"] != node
            or item["launch_token"] != runtime.plan["nodes"][node]["session_id"]):
        raise ValueError("Stale or foreign worker completion signal")
    statuses = {"completed", "blocked", "question"} if evidence else {"completed", "blocked"}
    if item["status"] not in statuses or not isinstance(item["summary"], str) or not item["summary"].strip():
        raise ValueError("Invalid completion status/summary")
    if not isinstance(item["open_assumptions"], list) or any(not isinstance(x, str) for x in item["open_assumptions"]):
        raise ValueError("Invalid completion assumptions")
    if evidence:
        completed = item["status"] == "completed"
        untested = item["untested"]
        if not (isinstance(untested, list) and all(isinstance(x, str) for x in untested) or (untested is None and not completed)):
            raise ValueError("Invalid completion evidence: untested must be a list of strings")
        if not text_or_none(item["falsifying_check"], completed) or not text_or_none(item["verify_yourself"], completed):
            raise ValueError("Invalid completion evidence: a completed 1.1.0 completion needs a non-empty falsifying_check and verify_yourself")
        if item["status"] == "question" and not text_or_none(item["question"], True):
            raise ValueError("Invalid completion: status question needs a non-empty question")
        if completed and item["question"] is not None:
            raise ValueError("Invalid completion: a completed file has question null")
    return item


def read_completion(runtime, node: str) -> dict:
    item = read_signal(runtime, node)
    if item["status"] == "blocked":
        raise RuntimeError(f"Worker {node} explicitly blocked: {item['summary']}")
    if item["status"] == "question":
        raise RuntimeError(f"Worker {node} asked a question that is not recorded yet: {item['question']}")
    return {"summary": item["summary"], "open_assumptions": item["open_assumptions"]}


def lanes(runtime) -> list[str]:
    """The run's selected lanes, from the runtime when it resolved them or from its plan."""
    return list(getattr(runtime, "workers", None) or plan_workers(runtime.plan))


def wait_handoffs(runtime, *, clock=time.time, sleep=time.sleep) -> None:
    """Idle alone never means completion. Deadlines survive controller restart.

    A 1.1.0 `question` completion pauses only that lane's deadline (persisted in `<node>.deadline.json`) until the
    operator answers, with `workflow answer` or by typing in the pane; the other lanes keep running.
    """
    from .guardrails import PANE_ANSWER, deadline_extension, load_questions, record_answer, record_question, waiting_question
    validate_automatic(runtime.plan)
    workers = lanes(runtime)
    if any((runtime.directory / f"{node}.stop.json").exists() for node in workers):
        # Recover a controller crash after durable handoffs/stop intent, before snapshot.
        for node in workers:
            if read_completion(runtime, node) != read_json(runtime.directory / f"{node}.handoff.json"):
                raise RuntimeError("Handoff changed after stop intent")
        return
    attention: set[str] = set()
    # Answers recorded before this controller started need no second event.
    answered = {(node, entry["n"]) for node in workers for entry in load_questions(runtime.directory, node) if entry["answer"] is not None}
    while True:
        rows = runtime.sessions.inventory()
        handoffs = {}
        for node in workers:
            receipt = read_json(runtime.directory / f"{node}.interactive.json")
            started = datetime.fromisoformat(receipt["launch_requested_at"]).timestamp()
            extension = deadline_extension(runtime.directory, node)  # None while a question waits: that lane has no running deadline.
            if extension is not None and clock() >= started + runtime.plan["automatic"]["worker_timeout_seconds"] + extension:
                raise RuntimeError(f"Worker {node} deadline exhausted; no automatic relaunch")
            row = runtime.sessions.locate(node, rows)
            if row is None:
                raise RuntimeError("Native worker missing; reconciliation required")
            if row["state"] == "working" and waiting_question(runtime.directory, node):
                # The operator typed the answer in the pane: the worker is working again, so its deadline runs again.
                record_answer(runtime.directory, node, PANE_ANSWER, clock)
            for entry in load_questions(runtime.directory, node):
                if entry["answer"] is not None and (node, entry["n"]) not in answered:
                    answered.add((node, entry["n"]))
                    runtime.event(node, "interactive", f"Worker {node} question {entry['n']} answered; its deadline runs again")
            if row["state"] == "blocked" and node not in attention:
                # A native session reports `blocked` when its turn ended needing a human: a question,
                # a permission prompt or a refusal the harness could not continue past. That is not a
                # failure of the lane, and the other lanes keep working. The operator may answer in the
                # pane; the worker deadline bounds the wait. No billing/provider fallback.
                attention.add(node)
                runtime.event(node, "interactive", f"Worker {node} needs attention in its pane (native state blocked); "
                                                   "waiting until its deadline")
            elif row["state"] != "blocked":
                attention.discard(node)
            path = runtime.directory / f"{node}.completion.json"
            if row["state"] in {"idle", "done"} and path.exists():
                if read_signal(runtime, node)["status"] == "question":
                    record_question(runtime, node, read_signal(runtime, node), clock)
                    continue
                handoffs[node] = read_completion(runtime, node)
        if set(handoffs) == set(workers):
            for node, value in handoffs.items():
                save_json(runtime.directory / f"{node}.handoff.json", value)
            return
        sleep(2)


# Finding attributions that name no single lane; the run's lane ids complete the vocabulary.
FINDING_ATTRIBUTIONS = ("multiple", "none")


def finding_workers(runtime) -> list[str]:
    """The `worker` vocabulary of this run's findings: its lane ids, then multiple and none."""
    return [*lanes(runtime), *FINDING_ATTRIBUTIONS]


def worker_vocabulary(runtime) -> str:
    """How the prompts spell the vocabulary: `ui, adapter, multiple or none`."""
    words = finding_workers(runtime)
    return ", ".join(words[:-1]) + " or " + words[-1]

def review_section(directory: Path) -> dict | None:
    review = load_optional(directory / "review.json")
    if review is None:
        return None
    receipt = load_optional(directory / "automatic-review.json") or {}
    transport = recorded_transport(directory) or "manual"
    reviewed_at = receipt.get("accepted_at")
    if not isinstance(reviewed_at, str):
        times = [event["time"] for event in read_events(directory) if event.get("node") == "review"]
        reviewed_at = times[-1] if times else utc((directory / "review.json").stat().st_mtime)
    diff = None
    patch = directory / "review.diff"
    if patch.is_file() and not patch.is_symlink():
        with patch.open("rb") as handle:
            diff = {"path": "review.diff", "sha256": hashlib.file_digest(handle, "sha256").hexdigest(), "bytes": patch.stat().st_size}
    findings = [{"severity": finding["severity"], "message": finding["message"], "disposition": finding["disposition"],
                 "worker": finding.get("worker"), "requirement": finding.get("requirement"),
                 "reviewer": finding.get("reviewer", DEFAULT_REVIEWER)} for finding in review["findings"]]
    return {"attempt": 1, "transport": transport, "reviewer_session_id": review["reviewer"], "independent": review["independent"],
            "bundle_sha256": review["bundle_sha256"], "candidate_commit": review["candidate_commit"], "verdict": review["verdict"],
            "findings": findings, "reviewers": reviewer_entries(directory, review, findings, transport, reviewed_at),
            "reviewed_at": reviewed_at, "diff": diff}


def launch_receipt(item) -> dict | None:
    if (not isinstance(item, dict) or not isinstance(item.get("launch_requested_at"), str) or not isinstance(item.get("launch_token"), str)
            or not isinstance(item.get("status"), str) or type(item.get("launcher_invocations")) is not int):
        return None
    optional = {key: item.get(key) if isinstance(item.get(key), str) else None for key in ("session_id", "observed_state", "background_id")}
    started = item.get("native_started_at")
    return {"session_id": optional["session_id"], "launch_token": item["launch_token"], "launch_requested_at": zulu(item["launch_requested_at"]),
            "native_started_at": started if type(started) is int else None, "observed_state": optional["observed_state"],
            "status": item["status"], "launcher_invocations": item["launcher_invocations"], "background_id": optional["background_id"]}


def optional_text(value) -> str | None:
    return value if isinstance(value, str) and value.strip() else None


def completion_signal(item) -> dict | None:
    """The worker's completion file; the 1.1.0 evidence is null when the file is 1.0.0 (or leaves a field empty)."""
    if (not isinstance(item, dict) or item.get("status") not in {"completed", "blocked", "question"} or not isinstance(item.get("summary"), str)
            or not item["summary"].strip() or not string_list(item.get("open_assumptions"))):
        return None
    untested = item.get("untested")
    return {"status": item["status"], "summary": item["summary"], "open_assumptions": list(item["open_assumptions"]),
            "untested": list(untested) if isinstance(untested, list) and all(isinstance(entry, str) for entry in untested) else None,
            "falsifying_check": optional_text(item.get("falsifying_check")), "verify_yourself": optional_text(item.get("verify_yourself"))}


QUESTION_KEYS = ("n", "question", "asked_at", "answer", "answered_at")


def worker_questions(path: Path) -> list:
    """`<node>.questions.json` as `{n, question, asked_at, answer, answered_at}` entries; `[]` when absent or malformed."""
    item = load_optional(path)
    questions = item.get("questions") if isinstance(item, dict) else None
    if not isinstance(questions, list):
        return []
    result = []
    for entry in questions:
        if (not isinstance(entry, dict) or type(entry.get("n")) is not int or not optional_text(entry.get("question"))
                or not isinstance(entry.get("asked_at"), str) or not (entry.get("answer") is None or isinstance(entry.get("answer"), str))
                or not (entry.get("answered_at") is None or isinstance(entry.get("answered_at"), str))
                or (entry.get("answer") is None) != (entry.get("answered_at") is None)):
            return []
        result.append({key: entry.get(key) for key in QUESTION_KEYS})
    return result


def challenge_section(directory: Path) -> dict | None:
    """The latest `challenge.json` without `run_id` and `version`, plus `attempts`; null when absent or invalid."""
    item = load_optional(directory / "challenge.json")
    if item is None:
        return None
    from jsonschema.exceptions import ValidationError
    from .verification import validate_schema
    try:
        validate_schema("challenge", item)
    except ValidationError:
        return None
    section = {key: value for key, value in item.items() if key not in {"run_id", "version"}}
    section["attempts"] = item["attempt"]
    return section


def accepted_handoff(item) -> dict | None:
    if not isinstance(item, dict) or not isinstance(item.get("summary"), str) or not item["summary"].strip() or not string_list(item.get("open_assumptions")):
        return None
    return {"summary": item["summary"], "open_assumptions": list(item["open_assumptions"])}


def stop_confirmation(path: Path) -> dict | None:
    item = load_optional(path)
    if not isinstance(item, dict) or not isinstance(item.get("stopped"), bool):
        return None
    return {"stopped": item["stopped"], "confirmed_at": utc(path.stat().st_mtime) if item["stopped"] else None}


def worker_inputs(directory: Path, plan: dict, policy: dict, worker: dict) -> dict:
    node = worker["node_id"]
    prompt = directory / f"{node}.prompt.txt"
    return {"role": worker["role"], "required_check_kinds": required_kinds(policy, worker), "task": plan["nodes"][node]["task"],
            "prompt": prompt.read_text() if prompt.is_file() and not prompt.is_symlink() else None,
            "owned_paths": list(worker["owned_paths"]),
            "checks": [{"id": check["id"], "kind": check["kind"], "argv": list(check["argv"]), "command": shlex.join(check["argv"]),
                        "timeout_seconds": check["timeout_seconds"],
                        "scenarios": [{"id": scenario["id"], "description": scenario["description"]} for scenario in check["scenarios"]]}
                       for check in worker["checks"]],
            "launch": launch_receipt(load_optional(directory / f"{node}.interactive.json")),
            "completion": completion_signal(load_optional(directory / f"{node}.completion.json")),
            "handoff": accepted_handoff(load_optional(directory / f"{node}.handoff.json")),
            "stop": stop_confirmation(directory / f"{node}.stop.json"),
            "questions": worker_questions(directory / f"{node}.questions.json")}


def inputs_section(directory: Path, plan: dict, policy: dict) -> dict:
    automatic = plan.get("automatic")
    workers = plan_workers(plan)

function Assumptions({ items }: { items: string[] }) {
  if (items.length === 0) return <p className="projects-muted">No open assumptions.</p>
  return <ul className="evidence-list">{items.map((item, index) => <li key={index}>{item}</li>)}</ul>
}

type Completion = NonNullable<RunInputWorker['completion']>
/** Where a check id named by the worker is shown: the verify node, and the executed check it matched by command when known. */
export type CheckTarget = { href: string; label: string }

const COMPLETION_BADGE: Record<Completion['status'], string> = { completed: 'status-succeeded', blocked: 'status-failed', question: 'status-awaiting_approval' }

/**
 * The falsifying check the worker named: a declared check id links to the verify node that shows that check executed; a
 * command equal to a declared check's command is treated the same; anything else is shown as the worker wrote it.
 */
function FalsifyingCheck({ value, worker, result, checksNode, onNavigate }: {
  value: string
  worker: RunInputWorker
  result: Resource<WorkerResult>
  checksNode: CheckTarget | null
  onNavigate: (pathname: string) => void
}) {
  const check = worker.checks.find(candidate => candidate.id === value) ?? worker.checks.find(candidate => candidate.command === value) ?? null
  if (check === null) {
    return <span data-testid="falsifying-check-text"><code>{value}</code> <span className="projects-muted">(not a check id declared for this lane)</span></span>
  }
  const executed = result.status === 'ready' ? result.data.checks.findIndex(candidate => candidate.command === check.command) : -1
  const where = executed === -1 ? '' : `, executed as check ${executed + 1}`
  const label = <><code>{check.id}</code> · <code>{check.command}</code></>
  if (checksNode === null) return <span data-testid="falsifying-check-text" data-check-id={check.id}>{label}</span>
  return (
    <AppLink
      href={checksNode.href}
      onNavigate={onNavigate}
      data-testid="falsifying-check-link"
      data-check-id={check.id}
      data-check-index={executed === -1 ? undefined : executed}
      title={`The executed check and its log are shown on ${checksNode.label}`}
    >
      {label} (on {checksNode.label}{where})
    </AppLink>
  )
}

/**
 * The evidence a 1.1.0 completion carries (PRD_PORTABLE_WORKFLOW 4.6): what no executed check covers, the check that would
 * fail if the implementation were wrong, and one assumption to verify independently. A 1.0.0 completion serves all three
 * as null, which is stated rather than shown as empty.
 */
function CompletionEvidence({ completion, worker, result, checksNode, onNavigate }: {
  completion: Completion
  worker: RunInputWorker
  result: Resource<WorkerResult>
  checksNode: CheckTarget | null
  onNavigate: (pathname: string) => void
}) {
  const { untested, falsifying_check: falsifying, verify_yourself: verify } = completion
  if (completion.status === 'question') {
    return (
      <p className="projects-muted" data-testid="completion-evidence-question">
        No completion evidence yet: the worker ended its turn with a question, listed below with its answer when there is one.
      </p>
    )
  }
  if (untested === null && falsifying === null && verify === null) {
    return (
      <p className="projects-muted" data-testid="completion-evidence-none">
        Completion evidence was not recorded for this run: its completion predates the untested, falsifying-check and verify-yourself fields.
      </p>
    )
  }
  return (
    <dl className="projects-facts completion-evidence" data-testid="completion-evidence">
      <div data-testid="evidence-untested">
        <dt>Untested</dt>
        <dd>
          {untested === null ? <span className="projects-muted">Not recorded</span>
            : untested.length === 0 ? <span className="projects-muted">Nothing: the worker names no behaviour outside its executed checks.</span>
              : <ul className="evidence-list">{untested.map((item, index) => <li key={index}>{item}</li>)}</ul>}
        </dd>
      </div>
      <div data-testid="evidence-falsifying-check">
        <dt>Falsifying check</dt>
        <dd>
          {falsifying === null || falsifying === ''
            ? <span className="projects-muted">Not recorded</span>
            : <FalsifyingCheck value={falsifying} worker={worker} result={result} checksNode={checksNode} onNavigate={onNavigate} />}
        </dd>
      </div>
      <div data-testid="evidence-verify-yourself">
        <dt>Verify yourself</dt>
        <dd>{verify === null || verify === '' ? <span className="projects-muted">Not recorded</span> : verify}</dd>
      </div>
    </dl>
  )
}

/** The questions the worker asked mid-run, with the operator's answers and times; an unanswered one is waiting on the operator. */
export function WorkerQuestions({ questions }: { questions: RunInputWorker['questions'] }) {
  const waiting = questions.filter(question => question.answer === null).length
  return (
    <section className="evidence-section" aria-labelledby="worker-questions-title" data-testid="worker-questions">
      <h4 id="worker-questions-title">Questions to the operator</h4>
      {questions.length === 0 ? (
        <p className="projects-muted" data-testid="worker-questions-none">No questions were recorded for this worker.</p>
      ) : (
        <>
          {waiting > 0 && (
            <p className="projects-notice" role="status" data-testid="worker-questions-waiting">
              {waiting === 1 ? 'One question is' : `${waiting} questions are`} waiting on the operator. Answers are given through the workflow CLI (<code>workflow answer</code>), not this viewer; the worker's deadline is paused meanwhile.
            </p>
          )}
          <ol className="evidence-list worker-questions" data-testid="worker-question-list">
            {questions.map(question => {
              const answered = question.answer !== null
              return (
                <li key={question.n} data-testid="worker-question" data-question={question.n} data-answered={answered ? 'true' : 'false'}>
                  <p>
                    <strong>Question {question.n}</strong> <span className="projects-muted">asked at {formatTime(question.asked_at)}</span>
                    {!answered && <> · <span className="status-badge status-awaiting_approval" data-testid="question-waiting"><span>Waiting on the operator</span></span></>}
                  </p>
                  <p className="worker-question-text">{question.question}</p>
                  {answered && (
                    <p className="worker-question-answer" data-testid="question-answer">
                      <strong>Answer</strong> <span className="projects-muted">at {question.answered_at === null ? 'an unrecorded time' : formatTime(question.answered_at)}</span>: {question.answer}
                    </p>
                  )}
                </li>
              )
            })}
          </ol>
        </>
      )}
    </section>
  )
}

/**
 * The worker's own completion signal with its evidence, and the accepted handoff only when it differs from it. `worker`,
 * `result` and `checksNode` let the falsifying check link to the executed check.
 */
export function WorkerSignals({ completion, handoff, worker, result, checksNode, onNavigate }: {
  completion: RunInputWorker['completion']
  handoff: RunInputWorker['handoff']
  worker: RunInputWorker
  result: Resource<WorkerResult>
  checksNode: CheckTarget | null
  onNavigate: (pathname: string) => void
}) {
  const handoffDiffers = handoff !== null && (
    completion === null || handoff.summary !== completion.summary || JSON.stringify(handoff.open_assumptions) !== JSON.stringify(completion.open_assumptions)

    completion === null || handoff.summary !== completion.summary || JSON.stringify(handoff.open_assumptions) !== JSON.stringify(completion.open_assumptions)
  )
  return (
    <>
      <section className="evidence-section" aria-labelledby="worker-completion-title" data-testid="worker-completion">
        <h4 id="worker-completion-title">Reported by the worker</h4>
        {completion === null ? (
          <p className="projects-muted">No completion signal recorded.</p>
        ) : (
          <>
            <p>
              <span className={`status-badge ${COMPLETION_BADGE[completion.status]}`} data-status={completion.status}><span>{completion.status}</span></span>
              {' '}<span className="projects-muted">as signalled by the session itself, not a verified result.</span>
            </p>
            <p className="worker-summary">{completion.summary}</p>
            <Assumptions items={completion.open_assumptions} />
            <CompletionEvidence completion={completion} worker={worker} result={result} checksNode={checksNode} onNavigate={onNavigate} />
          </>
        )}
      </section>
      {handoffDiffers && (
        <section className="evidence-section" aria-labelledby="worker-handoff-title" data-testid="worker-handoff">
          <h4 id="worker-handoff-title">Handoff as accepted</h4>
          <p className="projects-muted">The accepted handoff differs from what the worker reported.</p>
          <p className="worker-summary">{handoff.summary}</p>
          <Assumptions items={handoff.open_assumptions} />
        </section>
      )}
    </>
  )
}

export function StopLine({ stop }: { stop: RunInputWorker['stop'] }) {
  const confirmed = stop !== null && stop.stopped && stop.confirmed_at !== null
  return (
    <p className="worker-stop" data-testid="worker-stop">
      {confirmed
        ? `Stop confirmed at ${formatTime(stop.confirmed_at!)}.`
        : stop === null ? 'Stop not confirmed: no stop receipt was recorded.' : 'Stop not confirmed: the stop receipt records no confirmation.'}
    </p>
  )
}

